// Minimal CUDA Driver API surface, reached through dlopen. Types mirror
// cuda.h (CUcontext/CUmodule/CUfunction are opaque pointers; CUdeviceptr is
// an unsigned 64-bit device address) so no CUDA headers are required.
using CuResult = int;
using CuDeviceptr = unsigned long long;
using FnCuInit = CuResult (*)(unsigned);
using FnCuDeviceGet = CuResult (*)(int*, int);
using FnCuCtxCreate = CuResult (*)(unsigned long long*, unsigned, int);
using FnCuCtxDestroy = CuResult (*)(unsigned long long);
using FnCuModuleLoadData = CuResult (*)(unsigned long long*, const void*);
using FnCuModuleUnload = CuResult (*)(unsigned long long);
using FnCuModuleGetFunction = CuResult (*)(unsigned long long*, unsigned long long, const char*);
using FnCuMemAlloc = CuResult (*)(CuDeviceptr*, std::size_t);
using FnCuMemFree = CuResult (*)(CuDeviceptr);
using FnCuMemcpyHtoD = CuResult (*)(CuDeviceptr, const void*, std::size_t);
using FnCuMemcpyDtoH = CuResult (*)(void*, CuDeviceptr, std::size_t);
using FnCuLaunchKernel = CuResult (*)(unsigned long long, unsigned, unsigned, unsigned,
                                      unsigned, unsigned, unsigned, unsigned,
                                      unsigned long long, void**, void**);

struct LeanGpu {
    void* dl = nullptr;
    unsigned long long context = 0;
    unsigned long long module_qrlob = 0;
    unsigned long long module_ozaki = 0;
    unsigned long long module_lob_subgame = 0;
    unsigned long long module_lob_regret = 0;
    unsigned long long fn_rollout = 0;
    unsigned long long fn_ozaki = 0;
    unsigned long long fn_subgame = 0;
    unsigned long long fn_regret = 0;
    unsigned long long fn_regret_batch = 0;
    // Driver entry points (valid only while dl != nullptr).
    FnCuInit cuInit = nullptr;
    FnCuDeviceGet cuDeviceGet = nullptr;
    FnCuCtxCreate cuCtxCreate = nullptr;
    FnCuCtxDestroy cuCtxDestroy = nullptr;
    FnCuModuleLoadData cuModuleLoadData = nullptr;
    FnCuModuleUnload cuModuleUnload = nullptr;
    FnCuModuleGetFunction cuModuleGetFunction = nullptr;
    FnCuMemAlloc cuMemAlloc = nullptr;
    FnCuMemFree cuMemFree = nullptr;
    FnCuMemcpyHtoD cuMemcpyHtoD = nullptr;
    FnCuMemcpyDtoH cuMemcpyDtoH = nullptr;
    FnCuLaunchKernel cuLaunchKernel = nullptr;
    bool ready = false;
};

inline GpuStatus lean_gpu_init(LeanGpu* g) noexcept {
    if (g == nullptr) return GpuStatus::kBadArgs;
    g->dl = dlopen("libcuda.so.1", RTLD_NOW | RTLD_LOCAL);
    if (g->dl == nullptr) return GpuStatus::kNoDriver;
    g->cuInit = reinterpret_cast<FnCuInit>(dlsym(g->dl, "cuInit"));
    g->cuDeviceGet = reinterpret_cast<FnCuDeviceGet>(dlsym(g->dl, "cuDeviceGet"));
    g->cuCtxCreate = reinterpret_cast<FnCuCtxCreate>(dlsym(g->dl, "cuCtxCreate_v2"));
    g->cuCtxDestroy = reinterpret_cast<FnCuCtxDestroy>(dlsym(g->dl, "cuCtxDestroy_v2"));
    g->cuModuleLoadData = reinterpret_cast<FnCuModuleLoadData>(dlsym(g->dl, "cuModuleLoadData"));
    g->cuModuleUnload = reinterpret_cast<FnCuModuleUnload>(dlsym(g->dl, "cuModuleUnload"));
    g->cuModuleGetFunction = reinterpret_cast<FnCuModuleGetFunction>(dlsym(g->dl, "cuModuleGetFunction"));
    g->cuMemAlloc = reinterpret_cast<FnCuMemAlloc>(dlsym(g->dl, "cuMemAlloc_v2"));
    g->cuMemFree = reinterpret_cast<FnCuMemFree>(dlsym(g->dl, "cuMemFree_v2"));
    g->cuMemcpyHtoD = reinterpret_cast<FnCuMemcpyHtoD>(dlsym(g->dl, "cuMemcpyHtoD_v2"));
    g->cuMemcpyDtoH = reinterpret_cast<FnCuMemcpyDtoH>(dlsym(g->dl, "cuMemcpyDtoH_v2"));
    g->cuLaunchKernel = reinterpret_cast<FnCuLaunchKernel>(dlsym(g->dl, "cuLaunchKernel"));
    if (g->cuInit == nullptr || g->cuDeviceGet == nullptr || g->cuCtxCreate == nullptr ||
        g->cuModuleLoadData == nullptr || g->cuModuleGetFunction == nullptr ||
        g->cuMemAlloc == nullptr || g->cuMemFree == nullptr || g->cuMemcpyHtoD == nullptr ||
        g->cuMemcpyDtoH == nullptr || g->cuLaunchKernel == nullptr) {
        return GpuStatus::kNoDriver;
    }
    if (g->cuInit(0) != 0) return GpuStatus::kInitFailed;
    int device = -1;
    if (g->cuDeviceGet(&device, 0) != 0) return GpuStatus::kDeviceFailed;
    if (g->cuCtxCreate(&g->context, 0, device) != 0) return GpuStatus::kCtxFailed;

    // Load each PTX image into its own module and resolve entry points.
    if (g->cuModuleLoadData(&g->module_qrlob, kQrlobRolloutPtx) != 0) return GpuStatus::kModuleFailed;
    if (g->cuModuleGetFunction(&g->fn_rollout, g->module_qrlob,
                               "qrlob_gpu_batch_qr_hawkes_rollout_kernel") != 0) {
        return GpuStatus::kKernelMissing;
    }
    unsigned long long module_ozaki = 0;
    if (g->cuModuleLoadData(&module_ozaki, kQrlobOzakiPtx) != 0) return GpuStatus::kModuleFailed;
    g->module_ozaki = module_ozaki;
    if (g->cuModuleGetFunction(&g->fn_ozaki, module_ozaki,
                               "qrlob_gpu_ozaki_score_fisher_kernel") != 0) {
        return GpuStatus::kKernelMissing;
    }
    if (g->cuModuleLoadData(&g->module_lob_subgame, kLobSubgameCubin) != 0) return GpuStatus::kModuleFailed;
    if (g->cuModuleGetFunction(&g->fn_subgame, g->module_lob_subgame,
                               "solve_lob_subgame_kernel") != 0) {
        return GpuStatus::kKernelMissing;
    }
    if (g->cuModuleLoadData(&g->module_lob_regret, kLobRegretCubin) != 0) return GpuStatus::kModuleFailed;
    if (g->cuModuleGetFunction(&g->fn_regret, g->module_lob_regret,
                               "solve_lob_online_regret_kernel") != 0) {
        return GpuStatus::kKernelMissing;
    }
    if (g->cuModuleGetFunction(&g->fn_regret_batch, g->module_lob_regret,
                               "batch_online_regret_loop_kernel") != 0) {
        return GpuStatus::kKernelMissing;
    }
    g->ready = true;
    return GpuStatus::kOk;
}

inline GpuStatus lean_gpu_shutdown(LeanGpu* g) noexcept {
    if (g == nullptr) return GpuStatus::kBadArgs;
    if (g->module_qrlob != 0 && g->cuModuleUnload != nullptr) g->cuModuleUnload(g->module_qrlob);
    if (g->module_ozaki != 0 && g->cuModuleUnload != nullptr) g->cuModuleUnload(g->module_ozaki);
    if (g->module_lob_subgame != 0 && g->cuModuleUnload != nullptr) g->cuModuleUnload(g->module_lob_subgame);
    if (g->module_lob_regret != 0 && g->cuModuleUnload != nullptr) g->cuModuleUnload(g->module_lob_regret);
    if (g->context != 0 && g->cuCtxDestroy != nullptr) g->cuCtxDestroy(g->context);
    if (g->dl != nullptr) dlclose(g->dl);
    *g = LeanGpu{};
    return GpuStatus::kOk;
}

// Grid-stride batch rollout: one thread per trajectory, mirroring the kernel's
// step semantics on the host for the parity differential.
inline GpuStatus lean_gpu_rollout(LeanGpu* g, const std::uint64_t* states,
                                  const std::uint64_t* seeds, std::uint32_t* survival,
                                  float* intensity, std::int32_t n) noexcept {
    if (g == nullptr || !g->ready || states == nullptr || seeds == nullptr ||
        survival == nullptr || intensity == nullptr || n <= 0) {
        return GpuStatus::kBadArgs;
    }
    CuDeviceptr d_state = 0, d_seed = 0, d_survival = 0, d_intensity = 0;
    const std::size_t state_bytes = static_cast<std::size_t>(n) * sizeof(std::uint64_t);
    const std::size_t out_bytes = static_cast<std::size_t>(n) * sizeof(std::uint32_t);
    if (g->cuMemAlloc(&d_state, state_bytes) != 0) return GpuStatus::kAllocFailed;
    if (g->cuMemAlloc(&d_seed, state_bytes) != 0) { g->cuMemFree(d_state); return GpuStatus::kAllocFailed; }
    if (g->cuMemAlloc(&d_survival, out_bytes) != 0) { g->cuMemFree(d_state); g->cuMemFree(d_seed); return GpuStatus::kAllocFailed; }
    if (g->cuMemAlloc(&d_intensity, out_bytes) != 0) {
        g->cuMemFree(d_state); g->cuMemFree(d_seed); g->cuMemFree(d_survival);
        return GpuStatus::kAllocFailed;
    }
    GpuStatus st = GpuStatus::kOk;
    if (g->cuMemcpyHtoD(d_state, states, state_bytes) != 0 ||
        g->cuMemcpyHtoD(d_seed, seeds, state_bytes) != 0) {
        st = GpuStatus::kCopyFailed;
    }
    if (st == GpuStatus::kOk) {
        std::int32_t n_arg = n;
        void* args[5] = {&d_state, &d_seed, &d_survival, &d_intensity, &n_arg};
        const unsigned block = 256;
        const unsigned grid = (static_cast<unsigned>(n) + block - 1) / block;
        if (g->cuLaunchKernel(g->fn_rollout, grid, 1, 1, block, 1, 1, 0, 0, args, nullptr) != 0) {
            st = GpuStatus::kLaunchFailed;
        }
    }
    if (st == GpuStatus::kOk && g->cuMemcpyDtoH(survival, d_survival, out_bytes) != 0) st = GpuStatus::kCopyFailed;
    if (st == GpuStatus::kOk && g->cuMemcpyDtoH(intensity, d_intensity, out_bytes) != 0) st = GpuStatus::kCopyFailed;
    g->cuMemFree(d_state);
    g->cuMemFree(d_seed);
    g->cuMemFree(d_survival);
    g->cuMemFree(d_intensity);
    return st;
}

// 6-channel Ozaki sufficient-statistics kernel. Summation order on the GPU
// (warp butterfly + atomics) differs from a serial host loop, so callers must
// accept relaxed float parity (use ParityTolerance with ~1e-3 abs/rel).
// NOTE (warp uniformity): the kernel early-exits threads with idx >= n before
// its full-mask butterfly, so n must be a multiple of the launch block size
// for fully-defined shfl semantics on partial warps.
inline GpuStatus lean_gpu_ozaki(LeanGpu* g, const float* offsets,
                                const std::uint32_t* channels, const float* depths,
                                const float* mu, const float* gamma,
                                float* out_loglik, float* out_score, float* out_fisher,
                                std::int32_t n) noexcept {
    if (g == nullptr || !g->ready || offsets == nullptr || channels == nullptr ||
        depths == nullptr || mu == nullptr || gamma == nullptr || out_loglik == nullptr ||
        out_score == nullptr || out_fisher == nullptr || n <= 0) {
        return GpuStatus::kBadArgs;
    }
    CuDeviceptr d_off = 0, d_chan = 0, d_depth = 0, d_mu = 0, d_gamma = 0;
    CuDeviceptr d_ll = 0, d_sc = 0, d_fi = 0;
    const std::size_t ev_bytes = static_cast<std::size_t>(n) * sizeof(float);
    const std::size_t ch_bytes = static_cast<std::size_t>(n) * sizeof(std::uint32_t);
    bool ok = g->cuMemAlloc(&d_off, ev_bytes) == 0 &&
              g->cuMemAlloc(&d_chan, ch_bytes) == 0 &&
              g->cuMemAlloc(&d_depth, ev_bytes) == 0 &&
              g->cuMemAlloc(&d_mu, 6 * sizeof(float)) == 0 &&
              g->cuMemAlloc(&d_gamma, 6 * sizeof(float)) == 0 &&
              g->cuMemAlloc(&d_ll, sizeof(float)) == 0 &&
              g->cuMemAlloc(&d_sc, sizeof(float)) == 0 &&
              g->cuMemAlloc(&d_fi, sizeof(float)) == 0;
    if (!ok) {
        g->cuMemFree(d_off); g->cuMemFree(d_chan); g->cuMemFree(d_depth);
        g->cuMemFree(d_mu); g->cuMemFree(d_gamma);
        g->cuMemFree(d_ll); g->cuMemFree(d_sc); g->cuMemFree(d_fi);
        return GpuStatus::kAllocFailed;
    }
    GpuStatus st = GpuStatus::kOk;
    const float zero = 0.0f;
    if (g->cuMemcpyHtoD(d_off, offsets, ev_bytes) != 0 ||
        g->cuMemcpyHtoD(d_chan, channels, ch_bytes) != 0 ||
        g->cuMemcpyHtoD(d_depth, depths, ev_bytes) != 0 ||
        g->cuMemcpyHtoD(d_mu, mu, 6 * sizeof(float)) != 0 ||
        g->cuMemcpyHtoD(d_gamma, gamma, 6 * sizeof(float)) != 0 ||
        g->cuMemcpyHtoD(d_ll, &zero, sizeof(float)) != 0 ||
        g->cuMemcpyHtoD(d_sc, &zero, sizeof(float)) != 0 ||
        g->cuMemcpyHtoD(d_fi, &zero, sizeof(float)) != 0) {
        st = GpuStatus::kCopyFailed;
    }
    if (st == GpuStatus::kOk) {
        std::int32_t n_arg = n;
        void* args[9] = {&d_off, &d_chan, &d_depth, &d_mu, &d_gamma,
                         &d_ll, &d_sc, &d_fi, &n_arg};
        const unsigned block = 256;
        const unsigned grid = (static_cast<unsigned>(n) + block - 1) / block;
        if (g->cuLaunchKernel(g->fn_ozaki, grid, 1, 1, block, 1, 1, 0, 0, args, nullptr) != 0) {
            st = GpuStatus::kLaunchFailed;
        }
    }
    if (st == GpuStatus::kOk && g->cuMemcpyDtoH(out_loglik, d_ll, sizeof(float)) != 0) st = GpuStatus::kCopyFailed;
    if (st == GpuStatus::kOk && g->cuMemcpyDtoH(out_score, d_sc, sizeof(float)) != 0) st = GpuStatus::kCopyFailed;
    if (st == GpuStatus::kOk && g->cuMemcpyDtoH(out_fisher, d_fi, sizeof(float)) != 0) st = GpuStatus::kCopyFailed;
    g->cuMemFree(d_off); g->cuMemFree(d_chan); g->cuMemFree(d_depth);
    g->cuMemFree(d_mu); g->cuMemFree(d_gamma);
    g->cuMemFree(d_ll); g->cuMemFree(d_sc); g->cuMemFree(d_fi);
    return st;
}

// Generic launcher for the LOB subgame / online-regret kernels for callers
// that manage their own device buffers (wired into accelerator_parity flows).
inline GpuStatus lean_gpu_launch(LeanGpu* g, const char* kernel, void** args,
                                 unsigned grid_x, unsigned block_x) noexcept {
    if (g == nullptr || !g->ready || kernel == nullptr || args == nullptr ||
        grid_x == 0 || block_x == 0) {
        return GpuStatus::kBadArgs;
    }
    unsigned long long fn = 0;
    if (g->cuModuleGetFunction(&fn, g->module_lob_subgame, kernel) == 0) {
        // fallthrough with fn resolved from the subgame module
    } else if (g->cuModuleGetFunction(&fn, g->module_lob_regret, kernel) == 0) {
        // resolved from the regret module
    } else {
        return GpuStatus::kKernelMissing;
    }
    if (g->cuLaunchKernel(fn, grid_x, 1, 1, block_x, 1, 1, 0, 0, args, nullptr) != 0) {
        return GpuStatus::kLaunchFailed;
    }
    return GpuStatus::kOk;
}

